arguments.command:
export DRIVE_SESSION_TAG="${DRIVE_SESSION_TAG:-nothingness_linux_debug}"; export DRIVE_TARGET=linux; export DRIVE_RUN_LOG="/tmp/flutter_run_${DRIVE_SESSION_TAG}.log"; export DRIVE_DESKTOP_HOME="/tmp/nothingness_${DRIVE_SESSION_TAG}"; json=$( .agents/skills/agent-emulator-debugging/scripts/drive.py call ext.nothingness.getPlaybackState ); node <<'NODE'
const fs=require('fs');
const input=fs.readFileSync(0,'utf8');
const d=JSON.parse(input);
const queue=d.queue.map(t=>t.path);
const set=new Set(queue);
console.log('queueLength',queue.length);
console.log('uniquePaths',set.size);
NODE <<<"$json"

